files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: #1a1a2e;
  color: #e0e0e0;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
}

.card {
  background: #16213e;
  border: 3px solid #0f3460;
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 6px 6px 0 #0f3460;
}

h1 {
  font-size: 24px;
  text-align: center;
  margin-bottom: 16px;
  color: #e94560;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.stats {
  display: flex;
  justify-content: space-between;
  margin-bottom: 16px;
  font-size: 16px;
}

.stats strong {
  color: #e94560;
}

.input-row {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}

#todo-input {
  flex: 1;
  padding: 10px 12px;
  font-size: 16px;
  background: #1a1a2e;
  border: 2px solid #0f3460;
  color: #e0e0e0;
  outline: none;
}

#todo-input:focus {
  border-color: #e94560;
}

#todo-add {
  padding: 10px 20px;
  font-size: 16px;
  background: #e94560;
  color: #fff;
  border: 2px solid #e94560;
  cursor: pointer;
  font-weight: bold;
  transition: background 0.1s, transform 0.1s;
}

#todo-add:hover {
  background: #c73652;
  border-color: #c73652;
}

#todo-add:active {
  transform: translate(2px, 2px);
}

#todo-add:focus-visible {
  outline: 3px solid #e94560;
  outline-offset: 2px;
}

.todo-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.todo-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  background: #1a1a2e;
  border: 2px solid #0f3460;
}

.todo-item input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: #e94560;
  cursor: pointer;
  flex-shrink: 0;
}

.todo-item span {
  flex: 1;
  word-break: break-word;
}

.todo-item input[type="checkbox"]:checked + span {
  text-decoration: line-through;
  opacity: 0.6;
}

.todo-delete {
  background: transparent;
  border: 2px solid #e94560;
  color: #e94560;
  font-size: 14px;
  padding: 4px 8px;
  cursor: pointer;
  flex-shrink: 0;
  transition: background 0.1s, color 0.1s, transform 0.1s;
}

.todo-delete:hover {
  background: #e94560;
  color: #fff;
}

.todo-delete:active {
  transform: translate(1px, 1px);
}

.todo-delete:focus-visible {
  outline: 3px solid #e94560;
  outline-offset: 2px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 20px;
  }
  .input-row {
    flex-direction: column;
  }
  #todo-add {
    width: 100%;
  }
}

(() => {
  'use strict';

  const input = document.getElementById('todo-input');
  const addBtn = document.getElementById('todo-add');
  const list = document.getElementById('todo-list');
  const totalEl = document.getElementById('todo-total');
  const remainingEl = document.getElementById('remaining');

  let nextId = 1;
  const tasks = [];

  function updateCounts() {
    totalEl.textContent = String(tasks.length);
    const incomplete = tasks.filter(t => !t.done).length;
    remainingEl.textContent = String(incomplete);
  }

  function createTaskElement(task) {
    const li = document.createElement('li');
    li.className = 'todo-item';
    li.dataset.id = task.id;

    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.id = `todo-check-${task.id}`;
    checkbox.checked = task.done;
    checkbox.setAttribute('aria-label', `Mark "${task.text}" as ${task.done ? 'incomplete' : 'complete'}`);

    const span = document.createElement('span');
    span.id = `todo-text-${task.id}`;
    span.textContent = task.text;

    const delBtn = document.createElement('button');
    delBtn.type = 'button';
    delBtn.id = `todo-delete-${task.id}`;
    delBtn.className = 'todo-delete';
    delBtn.textContent = '\u2715';
    delBtn.setAttribute('aria-label', `Delete "${task.text}"`);

    checkbox.addEventListener('change', () => {
      task.done = checkbox.checked;
      checkbox.setAttribute('aria-label', `Mark "${task.text}" as ${task.done ? 'incomplete' : 'complete'}`);
      updateCounts();
    });

    delBtn.addEventListener('click', () => {
      const idx = tasks.findIndex(t => t.id === task.id);
      if (idx !== -1) tasks.splice(idx, 1);
      li.remove();
      updateCounts();
    });

    li.append(checkbox, span, delBtn);
    return li;
  }

  function addTask() {
    const text = input.value.trim();
    if (!text) return;

    const task = { id: nextId++, text, done: false };
    tasks.push(task);
    list.appendChild(createTaskElement(task));
    input.value = '';
    input.focus();
    updateCounts();
  }

  addBtn.addEventListener('click', addTask);
  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') addTask();
  });

  updateCounts();
})();
